/bin/bash -lc "python3 /workspace/tools.py resolve run://r-001 > /tmp/r001_contract.json
python3 - <<'PY'
import json
r=json.load(open('/tmp/r001_contract.json'))
print('KEYS',list(r))
for k,v in r.items():
 if k not in ['context','study_schema','candidate_api']: print(k,json.dumps(v,ensure_ascii=False))
print('CONTEXT KEYS',list(r['context']))
for k,v in r['context'].items():
 if k not in ['history','knowledge_access_log']: print(k,json.dumps(v,ensure_ascii=False)[:18000])
print('HISTORY SUMMARY')
for t in r['context'].get('history',[]):
 print(json.dumps({k:t.get(k) for k in ['id','parent','role','config','status','wall_seconds','validation','parameters','train_seconds','error','note']},ensure_ascii=False))
PY"

